/* The log1p feature tables (RsSlot.log1p, built by sim/native.py log1p_table): row k is float32(np.log1p(c) / K[k])
   for counts c in 0..RS_LOG1P_COUNTS-1. A count past the table (feedback XP is in tenths: one anchovy at XP_RATE 25
   is 10,000) is a late feature: rs_project writes 0 and lists it (RsLate: the float's byte offset in the packed row,
   its RS_LOG1P_* row, the count) in RsSlot.late_next; rs_commit_obs keeps the list with the row it describes
   (RsSlot.late), and after every call that writes rows sim/native.py NativeBatch writes float32(np.log1p(count) /
   K[k]) there (native.log1p_feature), the oracle's own expression evaluated in its process, so every count Python can
   produce is exact with no bound and no libm. RS_LATE_CAP: every log1p feature of one projection. */
#define RS_LOG1P_K {5.0, 10.0, 3.0, 12.0}
enum { RS_LOG1P_5 = 0, RS_LOG1P_10, RS_LOG1P_3, RS_LOG1P_12, RS_LOG1P_N };
#define RS_LOG1P_COUNTS 65536
#define RS_LATE_CAP (RS_OBSV_N_INV + RS_N_INV_SEL + RS_N_BANK_SEL + RS_N_HELD + 4)
typedef struct { int32_t off, k; int64_t count; } RsLate;

