    int32_t n_trees, n_rocks, n_gems, n_fish, n_eat_triggers, n_eat_rows, n_wield, n_styles, n_levelup, n_unlocks;
    const RsTreeRow *trees; const RsRockRow *rocks; const RsGemRow *gems; const RsFishRow *fish;
    const RsEatTrigger *eat_triggers; const RsEatRow *eat_rows; const RsWieldRule *wield;
