#undef RS_SCRIPT_ENUM
typedef struct { const char *name, *qualname; int status; } RsScriptInfo;
extern const RsScriptInfo RS_SCRIPT_INFO[RS_N_SCRIPTS];  /* pack.c */

/* Suspensions a script step returns (engine.py, 1390-1401). */
typedef enum { RS_DONE = 0, RS_PAUSE, RS_DELAY, RS_NPC_DELAY, RS_NPC_ARRIVEDELAY } RsSuspKind;
typedef struct { uint8_t kind; int32_t n; /* DELAY/NPC_DELAY: relative n; ARRIVEDELAY: the absolute tick */ } RsSusp;
/* p.script's state (engine.py): none, ('pausebutton'), ('suspended'), ('running'); an npc's script is none or
   suspended. */
enum { RS_SCRIPT_NONE = 0, RS_SCRIPT_PAUSE, RS_SCRIPT_SUSPENDED, RS_SCRIPT_RUNNING };

/* ---- per-world state ----------------------------------------------------------------------------------------- */
typedef struct { int32_t id, count; } Slot;  /* id < 0 empty; [id, 0] is an occupied slot (engine.py Inventory) */
enum { RS_INV_CAP = 28, RS_WORN_CAP = 14, RS_BANK_CAP = 240 };
enum { RS_REF_NONE = 0, RS_REF_NPC, RS_REF_LOC, RS_REF_OBJ, RS_REF_PLAYER };
typedef struct { uint8_t kind; uint8_t slot; uint16_t pad; uint32_t serial; } RsRef;

/* A generator object (one script frame chain). */
typedef struct {
    uint32_t serial;                           /* identity; 0 = no frame */
    uint8_t mode;                              /* RS_SCRIPT_* (as p.script's state; frames off p.script: 0) */
    uint8_t depth;                             /* levels in use, 1 + yield-from nesting */
    int16_t script[RS_FRAME_DEPTH];            /* RsScript of each level, outermost first */
    uint8_t pc[RS_FRAME_DEPTH];                /* suspension site of each level (pc convention above) */
    int32_t arg[RS_FRAME_DEPTH][RS_FRAME_ARGS]; /* each level's call arguments */
    RsRef ref[RS_FRAME_DEPTH];                 /* each level's entity argument (loc, npc or obj) */
    int32_t local[RS_FRAME_LOCALS];            /* locals live across a yield (the script decides; a death program:
                                                  local[0] its pc, [1] draws, [2] the hero found, [4..19] r0..r15) */
    int32_t ret;                               /* the last sub-level's return value */
} Frame;

/* A queued request: Request (engine.py) or an npc queue entry [id, arg, delay, source] (1083-1085). */
typedef struct {
    int32_t delay;
    int32_t arg[3];            /* player: the factory's bound args; npc: arg[0] = request arg, arg[1] = source is the
                                  player (1) or None (0) */
    int16_t script;            /* player: RsScript; npc: the queue id 1..3 */
    uint8_t kind;              /* RS_Q_NORMAL, RS_Q_WEAK, RS_Q_ENGINE (Request.kind; 'strong'/'soft' unused) */
    uint8_t in_list;           /* linked in its list now */
    int16_t prev, next;        /* links, -1 at the ends */
    int16_t dead_next;         /* unlinked during a pass, freed at its end */
    int16_t pad;
} Req;
enum { RS_Q_NORMAL = 0, RS_Q_WEAK, RS_Q_ENGINE };
typedef struct { int16_t head, tail; } ReqList;
/* One _links pass (engine.py). */
typedef struct { int16_t node, following; uint8_t ended; } RsLinks;

typedef struct {
    int32_t index;             /* Loc.index (oracle order) */
    uint32_t serial;           /* 0: free slot */
    int16_t base, type, x, z;
    uint8_t shape, angle, width, length, base_shape, base_angle, layer, level;
    uint8_t is_static, active;
    int32_t lifecycle;         /* lifecycle_tick, -1 untracked */
} Loc;

typedef struct {
    uint32_t serial;           /* 0: free slot */
    int16_t type, x, z;
    uint8_t level, is_static, active, receiver_player; /* receiver = the agent's player name, or None */
    int32_t count, ticks;
} Obj;

typedef struct {
    int16_t nid, base, type, x, z, start_x, start_z, size;
    uint8_t level, active, delayed, tele, observers;
    uint8_t target_player;     /* npc.target is the player (the only target) */
    uint8_t hunt_target_player;
    uint8_t has_path;          /* npc.path holds one waypoint (path_x, path_z) */
    int16_t mode, hunt_mode;
    int16_t huntrange, path_x, path_z;
    int32_t delayed_until, timer_interval, timer_clock, hunt_clock, regen_clock, stuck, lifecycle, last_movement;
    int32_t last_tick_x, last_tick_z, life;
    int16_t levels[6];
    uint8_t has_hero;          /* npc.heroes: at most the player's key */
    int32_t hero_damage;
    /* npc.vars (NPC_VARS, engine.py) */
    int32_t v_action_delay, v_lastcombat, v_xp_mult, v_stunned;
    uint8_t v_aggressive_player, v_attacking;  /* None or the player's name; macro_target stays None */
    ReqList queue;
    Frame script;              /* npc.script: a suspended generator (mode RS_SCRIPT_SUSPENDED) or none */
} Npc;

/* Player.varps in the oracle's insertion order (engine.py). aggressive_npc: uid, or -1 for None. */
#define RS_VARPS(X) X(action_delay) X(com_mode) X(bankcert) X(bankinsert) X(tutorial) X(lastcombat) \
